func (s *AccessSubscriptionsService) UnhidePosts(ctx context.Context, params AccessSubscriptionsUnhidePostsParams) (*AccessSubscriptionsUnhidePostsResponse, error) {
	if params.SubscriptionID == "" {
		return nil, missingParam("SubscriptionID")
	}
	req := &Request{Method: "DELETE", Path: "/v3/access/subscriptions/" + url.PathEscape(params.SubscriptionID) + "/hide-posts", Operation: "access.subscriptions.unhidePosts", LinkedAccount: true, LinkedAccountID: params.LinkedAccountID}
	var out AccessSubscriptionsUnhidePostsResponse
	if err := s.client.Do(ctx, req, &out); err != nil {
		return nil, err
	}
	return &out, nil
}
